Distance":[{"t":"Rest","lv":"JH"}]},"gfocus":{"JH Distance":"Rest","JH Mid Distance":"Rest"},"sess":{"JH":{"kind":"rest","title":"Rest","obj":"Championship week 1: WCJC and the Avon regional","wk":"JH championship week 1"}}}]},{"start":"2027-05-17","days":[{"day":"Mon","focus":{"JH":"Easy + mobility"},"all":[],"groups":{"Distance":[{"t":"State qualifiers: 20–30 min Easy + mobility","lv":"JH"},{"t":"Not running at state: season wrap-up week. Easy runs with the team, a relay day, and a summer plan talk.","lv":"JH"}],"Mid Distance":[{"t":"State qualifiers: 20–30 min Easy + mobility","lv":"JH"},{"t":"Not running at state: season wrap-up week. Easy runs with the team, a relay day, and a summer plan talk.","lv":"JH"}]},"gfocus":{"JH Distance":"Easy + mobility","JH Mid Distance":"Easy + mobility"},"sess":{"JH":{"kind":"official","title":"Easy + mobility","obj":"State week: freshness first","cls":"JH official practice (start date: confirm)","wk":"JH championship week 2"}}},{"day":"Tue","focus":{"JH":"Sharpen"},"all":[],"groups":{"Distance":[{"t":"State qualifiers: 2–3 × 150m relaxed fast, full recovery","lv":"JH"},{"t":"[A] Advanced 1600 runners may instead do 2 × 200m at 1600 pace (race rhythm), full recovery","lv":"JH"},{"t":"Not running at state: season wrap-up week. Easy runs with the team, a relay day, and a summer plan talk.","lv":"JH"}],"Mid Distance":[{"t":"State qualifiers: 2–3 × 150m relaxed fast, full recovery","lv":"JH"},{"t":"[A] Advanced 1600 runners may instead do 2 × 200m at 1600 pace (race rhythm), full recovery","lv":"JH"},{"t":"Not running at state: season wrap-up week. Easy runs with the team, a relay day, and a summer plan talk.","lv":"JH"}]},"gfocus":{"JH Distance":"Sharpen","JH Mid Distance":"Sharpen"},"sess":{"JH":{"kind":"official","title":"Sharpen","obj":"State week: freshness first","cls":"JH official practice (start date: confirm)","wk":"JH championship week 2"}}},{"day":"Wed","focus":{"JH":"Easy or rest"},"all":[],"groups":{"Distance":[{"t":"State qualifiers: 15–25 min Easy, or rest","lv":"JH"}],"Mid Distance":[{"t":"State qualifiers: 15–25 min Easy, or rest","lv":"JH"}]},"gfocus":{"JH Distance":"Easy or rest","JH Mid Distance":"Easy or rest"},"sess":{"JH":{"kind":"official","title":"Easy or rest","obj":"State week: freshness first","cls":"JH official practice (start date: confirm)","wk":"JH championship week 2"}}},{"day":"Thu","focus":{"JH":"Easy + strides"},"all":[],"groups":{"Distance":[{"t":"State qualifiers: 15–20 min Easy + 3 relaxed strides","lv":"JH"}],"Mid Distance":[{"t":"State qualifiers: 15–20 min Easy + 3 relaxed strides","lv":"JH"}]},"gfocus":{"JH Distance":"Easy + strides","JH Mid Distance":"Easy + strides"},"sess":{"JH":{"kind":"official","title":"Easy + strides","obj":"State week: freshness first","cls":"JH official practice (start date: confirm)","wk":"JH championship week 2"}}},{"day":"Fri","focus":{"JH":"Rest or shakeout"},"all":[],"groups":{"Distance":[{"t":"State qualifiers: rest or 10–15 min shakeout","lv":"JH"}],"Mid Distance":[{"t":"State qualifiers: rest or 10–15 min shakeout","lv":"JH"}]},"gfocus":{"JH Distance":"Rest or shakeout","JH Mid Distance":"Rest or shakeout"},"sess":{"JH":{"kind":"official","title":"Rest or shakeout","obj":"State week: freshness first","cls":"JH official practice (start date: confirm)","wk":"JH championship week 2"}}},{"day":"Sat","focus":{"JH":"Meet · MS State Finals"},"all":[],"groups":{"Distance":[{"t":"MEET: MS STATE FINALS, Indiana State University (qualifiers only)","lv":"JH"}],"Mid Distance":[{"t":"MEET: MS STATE FINALS, Indiana State University (qualifiers only)","lv":"JH"}]},"gfocus":{"JH Distance":"Meet · MS State Finals","JH Mid Distance":"Meet · MS State Finals"},"sess":{"JH":{"kind":"meet","title":"Meet · MS State Finals","obj":"State week: freshness first","wk":"JH championship week 2"}}},{"day":"Sun","focus":{"JH":"Rest"},"all":[],"groups":{"Distance":[{"t":"Rest. Great season.","lv":"JH"}],"Mid Distance":[{"t":"Rest. Great season.","lv":"JH"}]},"gfocus":{"JH Distance":"Rest","JH Mid Distance":"Rest"},"sess":{"JH":{"kind":"rest","title":"Rest","obj":"State week: freshness first","wk":"JH championship week 2"}}}]}]$plan$::jsonb;
  cur jsonb; w jsonb; d jsonb; wk jsonb; days jsonb; dd jsonb; keep jsonb; g text; grp jsonb; f jsonb;
  fw int; fd int; nd int := 0;
begin
  select value into cur from public.hub_data where key = 'workouts' for update;
  if cur is null or jsonb_typeof(cur) <> 'array' then cur := '[]'::jsonb; end if;
  for w in select * from jsonb_array_elements(plan) loop
    fw := null;
    for i in 0 .. jsonb_array_length(cur) - 1 loop
      if cur -> i ->> 'start' = w ->> 'start' then fw := i; end if;
    end loop;
    if fw is null then cur := cur || jsonb_build_array(w); nd := nd + jsonb_array_length(w -> 'days'); continue; end if;
    wk := cur -> fw;
    days := coalesce(wk -> 'days', '[]'::jsonb);
    for d in select * from jsonb_array_elements(w -> 'days') loop
      nd := nd + 1;
      fd := null;
      for j in 0 .. jsonb_array_length(days) - 1 loop
        if days -> j ->> 'day' = d ->> 'day' then fd := j; end if;
      end loop;
      if fd is null then days := days || jsonb_build_array(d); continue; end if;
      dd := days -> fd;
      if dd -> 'groups' is null or jsonb_typeof(dd -> 'groups') <> 'object' then dd := jsonb_set(dd, '{groups}', '{}'::jsonb); end if;
      for g, grp in select * from jsonb_each(d -> 'groups') loop
        select coalesce(jsonb_agg(x), '[]'::jsonb) into keep
          from jsonb_array_elements(coalesce(dd -> 'groups' -> g, '[]'::jsonb)) x
          where coalesce(x ->> 'lv', '') <> 'JH';
        dd := jsonb_set(dd, array['groups', g], keep || grp);
      end loop;
      dd := jsonb_set(dd, '{gfocus}', case when jsonb_typeof(dd -> 'gfocus') = 'object' then dd -> 'gfocus' else '{}'::jsonb end || (d -> 'gfocus'));
      dd := jsonb_set(dd, '{sess}', case when jsonb_typeof(dd -> 'sess') = 'object' then dd -> 'sess' else '{}'::jsonb end || (d -> 'sess'));
      -- JH focus label: keep the HS label
      f := dd -> 'focus';
      if f is null or jsonb_typeof(f) = 'null' or (jsonb_typeof(f) = 'string' and f #>> '{}' = '') then
        f := d -> 'focus';
      elsif jsonb_typeof(f) = 'string' then
        f := jsonb_build_object('HS', f #>> '{}', 'JH', d -> 'focus' ->> 'JH');
      else
        f := f || jsonb_build_object('JH', d -> 'focus' ->> 'JH');
      end if;
      dd := jsonb_set(dd, '{focus}', f);
      if dd -> 'all' is null then dd := dd || '{"all":[]}'::jsonb; end if;
      days := jsonb_set(days, array[fd::text], dd);
    end loop;
    select jsonb_agg(x order by array_position(array['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], x ->> 'day'))
      into days from jsonb_array_elements(days) x;
    cur := jsonb_set(cur, array[fw::text], jsonb_set(wk, '{days}', days));
  end loop;
  select jsonb_agg(x order by x ->> 'start') into cur from jsonb_array_elements(cur) x;
  insert into public.hub_data (key, value, updated_at) values ('workouts', cur, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  raise notice 'JH plan posted: % days (Dec 1 to May 23). % weeks in total.', nd, jsonb_array_length(cur);
end
$do$;
